mapper.select:
SELECT ROW_NUMBER() OVER ( ORDER BY
ev_date ev_cd dv_name dv_addr ev_car_num ev_date
ASC DESC
, ev_id DESC ) AS rn , A.* , B.dv_id , B.dv_addr , B.dv_name FROM tbl_event_data A LEFT JOIN tbl_device B ON A.ev_dv_id = B.dv_id
AND ( A.ev_car_num like CONCAT('%',#{searchKeyword},'%') OR B.dv_addr like CONCAT('%',#{searchKeyword},'%') OR B.dv_name like CONCAT('%',#{searchKeyword},'%'))
AND A.ev_date BETWEEN #{startDate} AND #{endDate}
AND A.ev_cd = #{evCd}
where 1=1
LIMIT #{recordCountPerPage}
OFFSET #{firstIndex}

SELECT COUNT(*) FROM tbl_event_data A LEFT JOIN tbl_device B ON A.ev_dv_id = B.dv_id
AND ( A.ev_car_num like CONCAT('%',#{searchKeyword},'%') OR B.dv_addr like CONCAT('%',#{searchKeyword},'%') OR B.dv_name like CONCAT('%',#{searchKeyword},'%'))
AND A.ev_date BETWEEN #{startDate} AND #{endDate}
AND A.ev_cd = #{evCd}

mapper.update:
UPDATE tbl_event_data
SET ev_has_img = 1
WHERE ev_id = #{evId}

UPDATE tbl_event_data
SET ev_has_mov = 1
WHERE ev_id = #{evId}
